#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void fused_matmul_sigmoid_sum_kernel(
    const float* x,
    const float* weight,
    const float* bias,
    float* output,
    int input_size,
    int hidden_size
) {
    extern __shared__ float shared_mem[];
    float* x_shared = shared_mem;
    float* shared_sum = shared_mem + input_size;

    int batch_idx = blockIdx.x;
    int thread_idx = threadIdx.x;

    const float* x_row = x + batch_idx * input_size;

    for (int k = thread_idx; k < input_size; k += blockDim.x) {
        if (k < input_size) x_shared[k] = x_row[k];
    }
    __syncthreads();

    if (thread_idx < hidden_size) {
        const float* w_row = weight + thread_idx * input_size;
        float sum = 0.0f;
        for (int k = 0; k < input_size; ++k) sum += x_shared[k] * w_row[k];
        sum += bias[thread_idx];
        float val = 1.0f / (1.0f + expf(-sum));

        shared_sum[thread_idx] = val;
        __syncthreads();

        for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
            if (thread_idx < stride) shared_sum[thread_idx] += shared_sum[thread_idx + stride];
            __syncthreads();
        }

        if (thread_idx == 0) output[batch_idx] = shared_sum[0];
    }
}

torch::Tensor fused_matmul_sigmoid_sum_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias
) {
    int batch_size = x.size(0);
    int input_size = x.size(1);
    int hidden_size = weight.size(0);

    auto output = torch::zeros({batch_size, 1}, x.options());
    dim3 grid(batch_size);
    dim3 block(hidden_size);
    size_t shared_mem_size = (input_size + hidden_size) * sizeof(float);

    fused_matmul_sigmoid_sum_kernel<<<grid, block, shared_mem_size>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        input_size,
        hidden_size
    );

    return output;
}
"""

